add_filter( 'woocommerce_sale_flash', 'perfectpixel_sale_end_date_badge', 40, 3 );

function perfectpixel_sale_end_date_badge( $html, $post, $product ) {
	if ( ! $html || ! $product ) {
		return $html;
	}
	$end = $product->get_date_on_sale_to();
	if ( ! $end || $end->getTimestamp() < time() ) {
		return $html;
	}
	$date = wp_date( '{{sale_end_format}}', $end->getTimestamp() );
	return preg_replace( '/<\/span>\s*$/', ' <small class="perfectpixel-sale-end">' . esc_html( '{{sale_end_prefix}} ' . $date ) . '</small></span>', $html, 1 );
}
